                    GridFormats.HrmAkceSimple = HrmAkceSimple;
                    function HrmAkceSimpleAsync() {
                        var gridFormat = new Gordic.Data.GridFormat();
                        Gordic.Eko.Grid.Column.addPid(gridFormat, { name: "ixp", field: "ixp" });
                        gridFormat
                            .addIconColumn({
                            name: "wiz_kind" /* Ddp.Interface.LK.Isl.GPripadDtoNames.wiz_kind */, caption: "Kontrola", width: 70, // vlastnosti přidaného sloupce
                            iconTemplate: function (data, meta) {
                                // pro virtuální řádek (součtový a podobně) se ikona nevrací
                                if (meta?._isVirtual)
                                    return null;
                                // sloupec do gridu timu ICON
                                if (data.wiz_kind === 200 /* Gordic.Isl.GOperationResultKind.Success */) // vyhovující doklad
                                    return { icon: "fa-check-circle g-state-success g-state-text", text: "OK", tooltip: "Vyhovující doklad" }; //RC 31850074 : 
                                else if (data.wiz_kind === 206 /* Gordic.Isl.GOperationResultKind.Warning */) // vyhovující doklad s upozorněním
                                    return { icon: "fa-exclamation-triangle g-state-warning g-state-text", text: "Varování", tooltip: "Vyhovující doklad s upozorněním" }; //RC 31850110 : Varování
                                else if (data.wiz_kind === 400 /* Gordic.Isl.GOperationResultKind.Error */) // nevyhovující doklad
                                    return { icon: "fa-times-circle g-state-error g-state-text", text: "Chyba", tooltip: "Nevyhovující doklad" }; //RC 31850111 : Chyba
                                else // žádný výsledek neexistuje
                                    return { icon: "", text: "", tooltip: "" }; // neutrální doklad
                            }
                        })
                            .addTextColumn({ name: "wiz_txt_err" /* Ddp.Interface.LK.Isl.GPripadDtoNames.wiz_txt_err */, caption: "Kontrola - výsledek" })
                            .addTextColumn({ name: "ExterniSubjekt.esu_txt", caption: "Poplatník", fragment: "ExterniSubjekt.Default" })
                            .add(Columns.lookup({ name: "typ_phl", caption: "Typ pohledávky" }, Columns.Cache.TypPhl))
                            .addVs();
                        return gridFormat;
                    }
                    GridFormats.HrmAkceSimpleAsync = HrmAkceSimpleAsync;
