                    /**
                     * Validace rodného čísla
                     * @param rc
                     * @returns
                     */
                    function validateRc(rc) {
                        const rcLen = rc.length;
                        if (rcLen === 9 || rcLen === 10) {
                            const s1 = rc.substring(0, 2);
                            const s2 = rc.substring(2, 4);
                            const s3 = rc.substring(4, 6);
                            if (s1 < "00" || s1 > "99") {
                                return false;
                            }
                            if (s2 < "01" || s2 > "62" || (s2 > "12" && s2 < "51")) {
                                return false;
                            }
                            let mes = parseInt(s2, 10);
                            if (mes > 50) {
                                mes -= 50;
                            }
                            if (mes === 2) {
                                if (s3 < "01" || s3 > "29") {
                                    return false;
                                }
                            }
                            else if ([4, 6, 9, 11].includes(mes)) {
                                if (s3 < "01" || s3 > "30") {
                                    return false;
                                }
                            }
                            else {
                                if (s3 < "01" || s3 > "31") {
                                    return false;
                                }
                            }
                            if (rcLen === 9) {
                                return true;
                            }
                            else {
                                const num = parseInt(rc.substring(0, 9), 10);
                                const kcis = num % 11;
                                if (parseInt(rc.substring(9, 10), 10) !== kcis) {
                                    return false;
                                }
                                return true;
                            }
                        }
                        return false;
                    }
